-- biped, generated by coilbox's unit builder.
-- Safe to edit: once you change this file, an export leaves it alone.

local base = piece("base")
local lthigh = piece("lthigh")
local lshin = piece("lshin")
local lfoot = piece("lfoot")
local rthigh = piece("rthigh")
local rshin = piece("rshin")
local rfoot = piece("rfoot")

local SIG_WALK_BIPED = 1

-- Walk, two legs
local function walk()
  SetSignalMask(SIG_WALK_BIPED)
  while true do
    Turn(lthigh, x_axis, 0.415, 2.075)
    Turn(lshin, x_axis, 0.1809, 0.9045)
    Turn(lfoot, x_axis, -0.5959, 2.9795)
    Turn(rthigh, x_axis, -0.415, 2.075)
    Turn(rshin, x_axis, 0.3427, 0.9045)
    Turn(rfoot, x_axis, 0.0723, 2.9795)
    Sleep(198)
    Turn(lthigh, x_axis, 0.2565, 0.7925)
    Turn(lshin, x_axis, 0.4736, 1.4635)
    Turn(lfoot, x_axis, -0.7301, 0.671)
    Turn(rthigh, x_axis, -0.2565, 0.7925)
    Turn(rshin, x_axis, 0.05, 1.4635)
    Turn(rfoot, x_axis, 0.2065, 0.671)
    Sleep(198)
    Turn(lthigh, x_axis, -0.2565, 2.565)
    Turn(lfoot, x_axis, -0.2171, 2.565)
    Turn(rthigh, x_axis, 0.2565, 2.565)
    Turn(rfoot, x_axis, -0.3065, 2.565)
    Sleep(198)
    Turn(lthigh, x_axis, -0.415, 0.7925)
    Turn(lshin, x_axis, 0.1809, 1.4635)
    Turn(lfoot, x_axis, 0.2341, 2.256)
    Turn(rthigh, x_axis, 0.415, 0.7925)
    Turn(rshin, x_axis, 0.3427, 1.4635)
    Turn(rfoot, x_axis, -0.7577, 2.256)
    Sleep(198)
    Turn(lthigh, x_axis, 0, 2.075)
    Turn(lshin, x_axis, 0, 0.9045)
    Turn(lfoot, x_axis, 0, 1.1705)
    Turn(rthigh, x_axis, 0, 2.075)
    Turn(rshin, x_axis, 0.5236, 0.9045)
    Turn(rfoot, x_axis, -0.5236, 1.1705)
    Sleep(198)
  end
end

local function walkStop()
  Turn(lthigh, x_axis, 0, 4)
  Turn(lshin, x_axis, 0, 4)
  Turn(lfoot, x_axis, 0, 4)
  Turn(rthigh, x_axis, 0, 4)
  Turn(rshin, x_axis, 0, 4)
  Turn(rfoot, x_axis, 0, 4)
end

function script.Create()
end

function script.StartMoving()
  Signal(SIG_WALK_BIPED)
  StartThread(walk)
end

function script.StopMoving()
  Signal(SIG_WALK_BIPED)
  walkStop()
end

function script.Activate()
end

function script.Deactivate()
end

function script.AimWeapon1(heading, pitch)
  return true
end

function script.AimFromWeapon1()
end

function script.QueryWeapon1()
end

function script.Shot1()
end

function script.StartBuilding(heading, pitch)
  SetUnitValue(COB.INBUILDSTANCE, 1)
end

function script.StopBuilding()
  SetUnitValue(COB.INBUILDSTANCE, 0)
end

function script.QueryNanoPiece()
  return base
end

function script.Killed(recentDamage, maxHealth)
  Explode(base, SFX.SHATTER)
  return 1
end
